fn solve(queries: Vec<(i8, i8)>) -> Vec<i8> {
    // Compute S(k) = sum_{i=1..k} a[i], where
    // a[i] = -i if i is odd, +i if i is even.
    // Known closed‐form:
    //   S(k) =  k/2        if k is even
    //         -(k+1)/2     if k is odd
    // We rewrite the odd case to avoid overflow on k+1:
    //   (k+1)/2 = k/2 + 1   for positive odd k
    // so  -(k+1)/2 = -(k/2) - 1.
    fn prefix(k: i8) -> i8 {
        let half = k / 2;
        if k % 2 == 0 {
            half
        } else {
            -half - 1
        }
    }

    let mut result = Vec::with_capacity(queries.len());
    for (l, r) in queries {
        // Sum over [l..r] = S(r) - S(l-1)
        let sum_r = prefix(r);
        let sum_lm1 = prefix(l - 1);
        result.push(sum_r - sum_lm1);
    }
    result
}

